from datetime import date as _date

def reconcile(bank, ledger, window=2):
    def parse(d):
        y, m, dd = d.split('-')
        return _date(int(y), int(m), int(dd))

    bank_sorted = sorted(enumerate(bank), key=lambda x: (x[1][1], x[1][0]))
    ledger_candidates = list(enumerate(ledger))

    used_ledger = set()
    matches = []
    unmatched_bank_idx = set()

    for orig_idx, b in bank_sorted:
        b_id, b_date, b_amt = b
        b_d = parse(b_date)
        best = None
        for l_idx, l in ledger_candidates:
            if l_idx in used_ledger:
                continue
            l_id, l_date, l_amt = l
            if l_amt != b_amt:
                continue
            l_d = parse(l_date)
            if abs((l_d - b_d).days) <= window:
                key = (l_d, l_id)
                if best is None or key < best[0]:
                    best = (key, l_idx, l_id)
        if best is not None:
            used_ledger.add(best[1])
            matches.append((b_id, best[2]))
        else:
            unmatched_bank_idx.add(orig_idx)

    unmatched_bank = [b[0] for i, b in enumerate(bank) if i in unmatched_bank_idx]
    unmatched_ledger = [l[0] for i, l in enumerate(ledger) if i not in used_ledger]

    return (matches, unmatched_bank, unmatched_ledger)
